program Collatz;
{$mode objfpc}{$H+}
var
  N, Steps: Integer;
begin
  N := 27;
  Steps := 0;
  while N <> 1 do
  begin
    if Odd(N) then N := 3 * N + 1 else N := N div 2;
    Inc(Steps);
  end;
  WriteLn(Steps);
end.

program Seven;
{$mode objfpc}{$H+}
var
  K: Integer;
begin
  for K := 1 to 10 do
    WriteLn(7 * K);
end.
